class Solution:
    def countBeautifulNumbers(self, l: int, r: int) -> int:
        from functools import lru_cache
        def f(x):
            if x <= 0:
                return 0
            ds = str(x)
            n = len(ds)
            @lru_cache(maxsize=None)
            def dp(i, s, p, tight, st):
                if i == n:
                    return 1 if st and p % s == 0 else 0
                hi = int(ds[i]) if tight else 9
                tot = 0
                for d in range(hi + 1):
                    nt = tight and d == hi
                    if not st and d == 0:
                        tot += dp(i + 1, 0, 1, nt, 0)
                    else:
                        tot += dp(i + 1, s + d, p * d, nt, 1)
                return tot
            return dp(0, 0, 1, True, False)
        return f(r) - f(l - 1)

