class Solution {
public:
    long long countBeautifulNumbers(int l, int r) {
        auto f = [&](long long x) -> long long {
            if (x <= 0) return 0;
            string ds = to_string(x);
            int n = ds.size();
            unordered_map<long long, long long> memo;
            function<long long(int,int,int,int,int)> dp = [&](int i, int s, int p, int tight, int st) -> long long {
                if (i == n) return (st && p % s == 0) ? 1 : 0;
                long long key = ((((((long long)i * 2 + tight) * 2 + st) * 91 + s) * 400000000LL) + p;
                auto it = memo.find(key);
                if (it != memo.end()) return it->second;
                int hi = tight ? ds[i] - '0' : 9;
                long long tot = 0;
                for (int d = 0; d <= hi; d++) {
                    int nt = tight && d == hi;
                    if (!st && d == 0) tot += dp(i + 1, 0, 1, nt, 0);
                    else tot += dp(i + 1, s + d, p * d, nt, 1);
                }
                return memo[key] = tot;
            };
            return dp(0, 0, 1, 1, 0);
        };
        return f(r) - f((long long)l - 1);
    }
};

