class Solution {
    public long countBeautifulNumbers(int l, int r) {
        return f(r) - f((long) l - 1);
    }
    private long f(long x) {
        if (x <= 0) return 0;
        String ds = Long.toString(x);
        int n = ds.length();
        Map<Long, Long> memo = new HashMap<>();
        return dp(0, 0, 1, 1, 0, ds, n, memo);
    }
    private long dp(int i, int s, int p, int tight, int st, String ds, int n, Map<Long, Long> memo) {
        if (i == n) return (st == 1 && p % s == 0) ? 1 : 0;
        long key = ((((((long) i * 2 + tight) * 2 + st) * 91 + s) * 400000000L) + p;
        Long got = memo.get(key);
        if (got != null) return got;
        int hi = tight == 1 ? ds.charAt(i) - '0' : 9;
        long tot = 0;
        for (int d = 0; d <= hi; d++) {
            int nt = (tight == 1 && d == hi) ? 1 : 0;
            if (st == 0 && d == 0) tot += dp(i + 1, 0, 1, nt, 0, ds, n, memo);
            else tot += dp(i + 1, s + d, p * d, nt, 1, ds, n, memo);
        }
        memo.put(key, tot);
        return tot;
    }
}

