var countBeautifulNumbers = function(l, r) {
    const f = x => {
        if (x <= 0) return 0;
        const ds = String(x), n = ds.length;
        const memo = new Map();
        const dp = (i, s, p, tight, st) => {
            if (i === n) return st && p % s === 0 ? 1 : 0;
            const key = (((((i * 2 + tight) * 2 + st) * 91 + s) * 4e8) + p);
            if (memo.has(key)) return memo.get(key);
            const hi = tight ? +ds[i] : 9;
            let tot = 0;
            for (let d = 0; d <= hi; d++) {
                const nt = tight && d === hi ? 1 : 0;
                if (!st && d === 0) tot += dp(i + 1, 0, 1, nt, 0);
                else tot += dp(i + 1, s + d, p * d, nt, 1);
            }
            memo.set(key, tot);
            return tot;
        };
        return dp(0, 0, 1, 1, 0);
    };
    return f(r) - f(l - 1);
};
